            aOrbiterE = (((aWandererC + RotL64(aCross, 53U)) + RotL64(aCarry, 41U)) + 0xD96BB5A88B9467BCULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 15U)) & S_SALT1];
