            //
            aOrbiterC = (aOrbiterC + aOrbiterG) + 0x26A05CE455D4FB9EULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterC) ^ 0xA5C2FAE916EC722DULL) ^ aTwistOrbiterUpdateSaltF[((aIndex + 11U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0xC4DDB13F934E3BD5ULL), 37U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterH) + 0x2141B6ED44C97E20ULL) + aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 22U)) & S_SALT1];
