            aOrbiterD = ((aWandererD + RotL64(aScatter, 34U)) + RotL64(aCarry, 5U)) + 0xC69833BCE059C6AFULL;
            aOrbiterB = (aWandererJ + RotL64(aIngress, 57U)) + 0x883C3DB1DBAA460EULL;
            aOrbiterI = ((aWandererG + RotL64(aPrevious, 27U)) + 0x58486DB8485287BFULL) + aTwistOrbiterAssignSaltE[((aIndex + 17U)) & S_SALT1];
            aOrbiterK = (aWandererH + RotL64(aCross, 3U)) + 0x73C5CE3EAB73870EULL;
            aOrbiterJ = (aWandererF + RotL64(aScatter, 13U)) + 0xE1C9CB2D0B7050C8ULL;
            aOrbiterG = (((aWandererI + RotL64(aPrevious, 47U)) + RotL64(aCarry, 29U)) + 0xFCAC44F727195B1DULL) + aTwistOrbiterAssignSaltC[(((31U - aIndex) + 21U)) & S_SALT1];
            //
            aOrbiterA = (aOrbiterA + aOrbiterD) + 0x77E0875230A6AF90ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterA) ^ 0x9E3092E5C1710262ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x0DA79C1EB53E2CF3ULL), 41U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterA) + 0xE79EA2AD9488EA38ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterI) ^ 0x88DB9F30625DB7ECULL) ^ aTwistOrbiterUpdateSaltF[((aIndex + 6U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xB7BE28B59D9298EFULL), 19U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterB) + 0x69493ACC69692AE3ULL) + aTwistOrbiterUpdateSaltD[((aIndex + 9U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterK) ^ 0x8F0D085AE5A26D8CULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x1D7C5C8A351906CFULL), 29U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterG) + 0xC8C665D40BAE9B74ULL;
