            aOrbiterI = RotL64((aOrbiterI * 0xDA7698CCDED4C98FULL), 13U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterK) + 0xEDA5DF0B360CE1ABULL) + aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterD) ^ 0xD3BD9CD51C94B8ABULL;
            aOrbiterG = RotL64((aOrbiterG * 0xA1A384FEC9EDD27DULL), 51U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterI) + 0x3AA19B72C8B6670CULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterJ) ^ 0x9ED0149847A913C5ULL) ^ aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x0D9F05D8C2C22B67ULL), 3U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterJ) + 0x53352E113761AF6CULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterG) ^ 0x90271245BD496B42ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xA4BF54BF0C213691ULL), 57U);
