            aCross = (RotL64(aFireLaneC[((S_BLOCK1 - aIndex + 13976U)) & S_BLOCK1], 5U) ^ RotL64(aEarthLaneC[((S_BLOCK1 - aIndex + 11290U)) & S_BLOCK1], 44U));
