            //
            aScatter = (RotL64(aIngress, 3U) ^ RotL64(aCarry, 27U)) ^ (RotL64(aPrevious, 54U) + RotL64(aCross, 41U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterE = (aWandererB + RotL64(aScatter, 35U)) + 0xAE0C13207B4B8D6BULL;
