            aWandererG = aWandererG + (((RotL64(aIngress, 29U) + RotL64(aOrbiterK, 51U)) + aOrbiterB) + RotL64(aCarry, 5U));
            aWandererA = aWandererA ^ (((RotL64(aPrevious, 51U) + RotL64(aOrbiterD, 27U)) + aOrbiterK) + aTwistWandererUpdateSaltE[(((31U - aIndex) + 24U)) & S_SALT1]);
