            //
            aOrbiterA = ((aWandererE + RotL64(aCross, 29U)) + RotL64(aCarry, 29U)) + 0xD7B649F57D972AEAULL;
            aOrbiterG = (aWandererI + RotL64(aIngress, 57U)) + 0xA824865FB278F43EULL;
            aOrbiterI = (aWandererC + RotL64(aPrevious, 19U)) + 0x6F1241B7A431F1BAULL;
            aOrbiterF = (aWandererJ + RotL64(aScatter, 42U)) + 0x47666D25F95E6644ULL;
            aOrbiterK = ((aWandererB + RotL64(aCross, 13U)) + 0x21F146C294486F85ULL) + aTwistOrbiterAssignSaltF[((aIndex + 21U)) & S_SALT1];
            aOrbiterD = ((aWandererA + RotL64(aPrevious, 51U)) + RotL64(aCarry, 47U)) + 0x2CA515B45D6C8DDBULL;
            aOrbiterH = (((aWandererD + RotL64(aIngress, 35U)) + RotL64(aCarry, 5U)) + 0xFD151E2155FB85B8ULL) + aTwistOrbiterAssignSaltA[((aIndex + 24U)) & S_SALT1];
            //
            aOrbiterA = (aOrbiterA + aOrbiterG) + 0x32388B76B736B96BULL;
