            //
            aOrbiterD = ((aOrbiterD + aOrbiterH) + 0x529F419F0721863DULL) + aTwistOrbiterUpdateSaltC[((aIndex + 18U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterD) ^ 0xAB89256150E02C58ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x936980F1D174ABC7ULL), 13U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterA) + 0x71FA0492B93F6C6BULL) + aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterH) ^ 0x316A203A1C7B854DULL;
            aOrbiterF = RotL64((aOrbiterF * 0x2985E20A4CAAB587ULL), 39U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterI) + 0x9758D32C41F38535ULL;
