            aWandererE = aWandererE ^ ((RotL64(aCross, 43U) + RotL64(aOrbiterG, 29U)) + aOrbiterB);
            //
            aCarry = aCarry + (RotL64(aWandererG, 23U) ^ aWandererJ);
