            aOrbiterJ = ((aWandererK + RotL64(aCross, 43U)) + RotL64(aCarry, 43U)) + 0xA2A272AAA458EA3AULL;
            aOrbiterA = (((aWandererH + RotL64(aPrevious, 3U)) + RotL64(aCarry, 3U)) + 0xEC3B89241D21AF66ULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 26U)) & S_SALT1];
