            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aPrevious, 52U) ^ RotL64(aCross, 27U)) + (RotL64(aCarry, 3U) + RotL64(aIngress, 39U));
            aScatter = TwistMix64::DiffuseB(aScatter);
            //
            aOrbiterB = (aWandererD + RotL64(aIngress, 21U)) + 0x9B3868203D8DA869ULL;
            aOrbiterJ = (aWandererG + RotL64(aPrevious, 37U)) + 0x8F867070181BC25EULL;
            aOrbiterF = ((aWandererJ + RotL64(aCross, 29U)) + RotL64(aCarry, 41U)) + 0x31DBCE7A97C88B9EULL;
            aOrbiterD = (aWandererK + RotL64(aScatter, 51U)) + 0xAAADC80C1C16089BULL;
