            aOrbiterK = (((aWandererC + RotL64(aScatter, 4U)) + RotL64(aCarry, 13U)) + 0xFD24D453B6E6D515ULL) + aKeyRotateOrbiterAssignSaltD[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterC = (((aWandererF + RotL64(aPrevious, 57U)) + RotL64(aCarry, 29U)) + 0x1465DCF1CFEB7634ULL) + aKeyRotateOrbiterAssignSaltF[(((31U - aIndex) + 19U)) & S_SALT1];
            //
            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0x7B1883F150CE2B1EULL;
