            aOrbiterD = (aOrbiterD + aOrbiterF) + 0x53F4CC7ABA1226C5ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterD) ^ 0xD2B18BA5A6DBA0E0ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x105C3C2344DA0A33ULL), 41U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterG) + 0xC8D7BBA9D13FA49CULL) + aKeyRotateOrbiterUpdateSaltB[((aIndex + 10U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterK) ^ 0xD49822E9B894D056ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x59F2B526092E51BFULL), 11U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterC) + 0x8D32CB99F7B414A2ULL) + aKeyRotateOrbiterUpdateSaltE[((aIndex + 23U)) & S_SALT1];
