            aOrbiterJ = RotL64((aOrbiterJ * 0xC4AC6E53BCEB13D7ULL), 47U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterB) + 0x95BCC1C712775E96ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterC) ^ 0x3312C8C8D84203D6ULL) ^ aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x9DA66E789757D0E3ULL), 3U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterK) + 0xC5D90336555893D5ULL;
