            //
            aOrbiterJ = (aOrbiterJ + aOrbiterD) + 0xB5027C2879BEEA8CULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterJ) ^ 0x5DA97D1B795A6FE1ULL) ^ aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xEF5B9F61CDDE52ABULL), 35U);
