            aWandererA = aWandererA + ((RotL64(aPrevious, 47U) + RotL64(aOrbiterB, 23U)) + aOrbiterG);
            aWandererD = aWandererD ^ (((RotL64(aCross, 42U) + aOrbiterB) + RotL64(aOrbiterI, 43U)) + aKeyRotateWandererUpdateSaltD[(((31U - aIndex) + 20U)) & S_SALT1]);
