            aOrbiterC = (((aWandererH + RotL64(aScatter, 56U)) + RotL64(aCarry, 51U)) + 0xCC2E9D852DF4633EULL) + aKeyRotateOrbiterAssignSaltA[((aIndex + 19U)) & S_SALT1];
