            //
            aOrbiterE = ((aOrbiterE + aOrbiterJ) + 0xA84169528B9CAE43ULL) + aKeyRotateOrbiterUpdateSaltE[((aIndex + 8U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0x04985AB78EF0F389ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xFC266A7F574A4221ULL), 57U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterI) + 0x3428922ECE7DA3CAULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0x3A46289599C2D283ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xD9036B1F52EB684DULL), 27U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterG) + 0x69DD4C63EDE50E45ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterI) ^ 0x56F4811474FB8DFDULL;
            aOrbiterF = RotL64((aOrbiterF * 0x27E8E4CD19592A17ULL), 21U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterB) + 0xF20CD205BDD6E0D8ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0xEF93F495D1065523ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xACE4CC214C817ACFULL), 5U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterC) + 0x3C386DBE083AD6D2ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterJ) ^ 0x9C4994FC6ACE3E7EULL;
            aOrbiterI = RotL64((aOrbiterI * 0xD588EBB3B4558211ULL), 51U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterA) + 0x53E445F8F1949D35ULL) + aKeyRotateOrbiterUpdateSaltD[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterG) ^ 0x6EB554101F83DD69ULL;
