            aOrbiterC = (aOrbiterC + aOrbiterK) + 0x0D903E227AA48912ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0x8CF187F3DF9C784EULL;
            aOrbiterG = RotL64((aOrbiterG * 0x5EDC97BAC22909F1ULL), 37U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterD) + 0x6F07091E98887377ULL) + aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterB) ^ 0x76218C618EB3EC31ULL;
