            aCross ^= (RotL64(aPoisonLaneA[((S_BLOCK1 - aIndex + 5733U)) & S_BLOCK1], 41U) ^ RotL64(aPoisonLaneC[((aIndex + 4085U)) & S_BLOCK1], 14U));
            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aCross, 11U) + RotL64(aIngress, 41U)) ^ (RotL64(aPrevious, 53U) + RotL64(aCarry, 26U));
