            //
            aOrbiterI = ((aWandererJ + RotL64(aCross, 29U)) + RotL64(aCarry, 27U)) + 0x3C46A838849CB49BULL;
            aOrbiterH = ((aWandererB + RotL64(aIngress, 11U)) + 0x9371A0E958925270ULL) + aKeyRotateOrbiterAssignSaltB[(((31U - aIndex) + 12U)) & S_SALT1];
            aOrbiterK = (((aWandererA + RotL64(aScatter, 60U)) + RotL64(aCarry, 13U)) + 0xA05E23E6CF658A6DULL) + aKeyRotateOrbiterAssignSaltA[((aIndex + 11U)) & S_SALT1];
            aOrbiterJ = (aWandererG + RotL64(aPrevious, 23U)) + 0x65766A2A28B6B05DULL;
            aOrbiterE = (aWandererF + RotL64(aScatter, 47U)) + 0x0DB8BEA4A777D5CFULL;
            aOrbiterC = (aWandererE + RotL64(aPrevious, 5U)) + 0x5E6DCBB899EF6FBCULL;
