            aOrbiterF = RotL64((aOrbiterF * 0x087C173D5DAB0839ULL), 57U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterD) + 0xD4C51EEA140714C0ULL) + aKeyRotateOrbiterUpdateSaltD[((aIndex + 3U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterA) ^ 0xE518D7A4967E8A19ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x70BBE5570DA32BD5ULL), 21U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterA) + 0xBE262F0DC26E380EULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterG) ^ 0xA2AF759060951FBDULL) ^ aKeyRotateOrbiterUpdateSaltF[((aIndex + 24U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x5DAA579B49CB998DULL), 27U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterF) + 0x4203109C3B86D1EEULL) + aKeyRotateOrbiterUpdateSaltB[((aIndex + 9U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterE) ^ 0x6D133B79CE127A8EULL;
            aOrbiterI = RotL64((aOrbiterI * 0xBA8AB1D2469BA1B5ULL), 35U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterK) + 0xAE8A8F1BF6DE6CCBULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterI) ^ 0x46A8E24716205EFEULL) ^ aKeyRotateOrbiterUpdateSaltA[(((31U - aIndex) + 20U)) & S_SALT1];
