            aWandererA = aWandererA ^ ((RotL64(aScatter, 51U) + RotL64(aOrbiterF, 29U)) + aOrbiterI);
            aWandererC = aWandererC + (((RotL64(aPrevious, 21U) + aOrbiterK) + RotL64(aOrbiterI, 41U)) + RotL64(aCarry, 43U));
