            aOrbiterF = (((aWandererC + RotL64(aIngress, 4U)) + RotL64(aCarry, 29U)) + 0xB220CAEAB864B21AULL) + aKeySpawnOrbiterAssignSaltF[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterJ = ((aWandererB + RotL64(aScatter, 43U)) + RotL64(aCarry, 51U)) + 0xD32AF38E52AD0487ULL;
