            aOrbiterD = (aWandererD + RotL64(aPrevious, 57U)) + 0x3BB9ACB991925912ULL;
            aOrbiterB = (aWandererA + RotL64(aScatter, 26U)) + 0x3E7C45B340E921BCULL;
            aOrbiterI = ((aWandererH + RotL64(aPrevious, 13U)) + RotL64(aCarry, 13U)) + 0xFA0FDCAE56D7AE62ULL;
            //
            aOrbiterC = (aOrbiterC + aOrbiterG) + 0x4A8379D33AADE652ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterC) ^ 0x6315CE1AF7E9E792ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xF81D8DBA47761E83ULL), 47U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterJ) + 0x12983D123E3533AEULL) + aKeySpawnOrbiterUpdateSaltC[((aIndex + 27U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0x8AAECA7A4B3DEF25ULL;
