            //
            aOrbiterH = ((aOrbiterH + aOrbiterA) + 0xD083EAC5FB93F857ULL) + aKeySpawnOrbiterUpdateSaltD[((aIndex + 17U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterH) ^ 0x181301A5F7DB4097ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x686C6E03F1660EE1ULL), 41U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterB) + 0xEF99652D71433B47ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterJ) ^ 0x24386723E6F113C4ULL;
