            aIngress = (RotL64(aFuseLaneA[((aIndex + 8926U)) & S_BLOCK1], 52U) ^ RotL64(aCelestialLaneC[((aIndex + 15153U)) & S_BLOCK1], 37U));
            aIngress ^= (RotL64(aAetherLaneD[((aIndex + 9890U)) & S_BLOCK1], 5U) ^ RotL64(aAetherLaneA[((S_BLOCK1 - aIndex + 9034U)) & S_BLOCK1], 29U));
            aIngress = TwistMix64::DiffuseA(aIngress);
            //
            aCross = (RotL64(aCelestialLaneA[((S_BLOCK1 - aIndex + 13917U)) & S_BLOCK1], 46U) ^ RotL64(aCelestialLaneD[((S_BLOCK1 - aIndex + 12886U)) & S_BLOCK1], 19U));
            aCross ^= (RotL64(aKineticLaneA[((S_BLOCK1 - aIndex + 9439U)) & S_BLOCK1], 5U) ^ RotL64(aKeyRowReadA[(((2047U - aIndex) + 13758U)) & W_KEY1], 29U));
