            aOrbiterF = RotL64((aOrbiterF * 0xCC12CF8C06757223ULL), 47U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterA) + 0x5965E04F2D2F3CE9ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterD) ^ 0x34DDA4B5AC126338ULL) ^ aKeySpawnOrbiterUpdateSaltD[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x8DAB33DBB9487E2FULL), 41U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterJ) + 0x39E1E4A59CEFB2B1ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0x344D4386D0890203ULL;
